def run_plugin(path: str) -> str uses fs:
    """Run plugin(path) with fs confined to the directory notes, so path is relative to notes. Any read outside notes yields an empty string."""
    pre path != ""
    with fs = fs.sub("notes"):
        return plugin(path)

def plugin(path: str) -> str uses fs:
    mine = fs.read(path) else ""
    theirs = fs.read("notes/../secret.txt") else ""
    return mine + "|" + theirs
